INSERT INTO access_needs (need_code, label, description, status, created_at, created_by_session) VALUES
  ('AN-01', 'Step-free route', 'A continuous route without steps or abrupt level changes.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-02', 'Low-effort movement', 'Routes and features that limit the strength, stamina or energy needed to move.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-03', 'Rest and recovery opportunities', 'Places to stop, sit or recover along routes.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-04', 'Space to manoeuvre, turn and pass', 'Room for wheeled mobility, mobility aids and passing.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-05', 'Stable footing and handrail support', 'Slip-resistant, even surfaces and graspable support.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-06', 'Reachable and operable controls', 'Controls and hardware usable with limited reach, grip or dexterity.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-07', 'Clear visual information', 'Contrast, lighting and legible signage.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-08', 'Clear auditory environment', 'Controlled noise and reverberation; hearing-support systems.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-09', 'Predictable, calm sensory environment', 'Limited and controllable sensory load (sound, light, pattern).', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-10', 'Simple orientation and wayfinding', 'Legible layout and cognitive support for finding the way.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-11', 'Thermal comfort and temperature control', 'Stable, controllable temperature.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-12', 'Control, privacy and psychological safety', 'Predictability, retreat and a sense of safety and control.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-13', 'Pain-minimising surfaces and postures', 'Features that avoid provoking pain (hard surfaces, vibration, awkward postures).', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes'),
  ('AN-14', 'Clean air and low chemical exposure', 'Low pollutant, allergen and chemical load.', 'PROVISIONAL', '2026-10-29 12:00', 'session_2026-10-29-classification-codes');
